281	/// The composer row — "+" (`InsertionModal.show`, unchanged), a text
282	/// field (placeholder "Escreva uma mensagem...") and a send icon. The
283	/// text field and send icon are disabled while the bootstrap hasn't
284	/// resolved yet or while an AI bubble is still `streaming` (Code
285	/// Map/`ChatCubit.sendMessage`'s own same-shaped guard); the "+" stays
286	/// tappable regardless, same as the deleted placeholder's own
287	/// always-tappable "+" — never a dedicated offline banner/lock, that's
288	/// Story 6.3's job (Boundaries).
289	class _ChatComposer extends StatelessWidget {
290	  const _ChatComposer({
291	    required this.controller,
292	    required this.focusNode,
293	    required this.onSend,
294	  });
