320	                      photoCubit: sl<PhotoEntryCubit>(),
321	                    ),
322	                    icon: const Icon(Icons.add, color: DesignTokens.colorPrimary),
323	                  ),
324	                ),
325	                Expanded(
326	                  child: TextField(
327	                    controller: controller,
328	                    focusNode: focusNode,
329	                    enabled: canSend,
