331	                    // `content` at 8000 characters (openapi.yaml) — a
332	                    // client-side cap surfaces that limit directly
333	                    // instead of letting an over-length message fail
334	                    // only after a round trip, indistinguishable from a
335	                    // dropped connection.
336	                    maxLength: 8000,
337	                    textInputAction: TextInputAction.send,
338	                    onSubmitted: canSend ? (_) => onSend() : null,
339	                    style: DesignTokens.textBodyLg.copyWith(
340	                      color: DesignTokens.colorTextPrimary,
341	                    ),
342	                    decoration: InputDecoration(
