344	                      counterText: '',
345	                      contentPadding: DesignTokens.textFieldContentPadding,
346	                      border: const OutlineInputBorder(
347	                        borderRadius: BorderRadius.all(
348	                          Radius.circular(DesignTokens.radiusFull),
349	                        ),
350	                        borderSide: BorderSide(
351	                          color: DesignTokens.colorBorder,
352	                          width: DesignTokens.borderWidthDefault,
353	                        ),
354	                      ),
355	                      enabledBorder: const OutlineInputBorder(
356	                        borderRadius: BorderRadius.all(
357	                          Radius.circular(DesignTokens.radiusFull),
358	                        ),
359	                        borderSide: BorderSide(
360	                          color: DesignTokens.colorBorder,
361	                          width: DesignTokens.borderWidthDefault,
362	                        ),
363	                      ),
364	                      focusedBorder: const OutlineInputBorder(
365	                        borderRadius: BorderRadius.all(
366	                          Radius.circular(DesignTokens.radiusFull),
367	                        ),
368	                        borderSide: BorderSide(
369	                          color: DesignTokens.colorPrimary,
370	                          width: DesignTokens.borderWidthEmphasis,
371	                        ),
372	                      ),
373	                    ),
374	                  ),
375	                ),
376	                Semantics(
377	                  button: true,
378	                  label: 'Enviar mensagem',
379	                  excludeSemantics: true,
380	                  child: IconButton(
381	                    onPressed: canSend ? onSend : null,
382	                    icon: Icon(
383	                      Icons.send,
384	                      color: canSend
385	                          ? DesignTokens.colorPrimary
386	                          : DesignTokens.colorTextSecondary,
387	                    ),
388	                  ),
389	                ),
390	              ],
391	            ),
392	          ),
393	        );
394	      },
395	    );
396	  }
397	}
