/// The composer row — "+" (`InsertionModal.show`, unchanged), a text
/// field (placeholder "Escreva uma mensagem...") and a send icon. The
/// text field and send icon are disabled while the bootstrap hasn't
/// resolved yet or while an AI bubble is still `streaming` (Code
/// Map/`ChatCubit.sendMessage`'s own same-shaped guard); the "+" stays
/// tappable regardless, same as the deleted placeholder's own
/// always-tappable "+" — never a dedicated offline banner/lock, that's
/// Story 6.3's job (Boundaries).
class _ChatComposer extends StatelessWidget {
  const _ChatComposer({
    required this.controller,
    required this.focusNode,
    required this.onSend,
  });

  final TextEditingController controller;
  final FocusNode focusNode;
  final VoidCallback onSend;

  @override
  Widget build(BuildContext context) {
    return BlocBuilder<ChatCubit, ChatState>(
      builder: (context, state) {
        final canSend = state is ChatReady && !state.isSending;
        return SafeArea(
          top: false,
          child: Padding(
            padding: DesignTokens.screenPadding,
            child: Row(
              children: [
                Semantics(
                  button: true,
                  label: 'Adicionar registro',
                  excludeSemantics: true,
                  child: IconButton(
                    onPressed: () => InsertionModal.show(
                      context,
                      cubit: sl<TextEntryCubit>(),
                      audioCubit: sl<AudioEntryCubit>(),
                      photoCubit: sl<PhotoEntryCubit>(),
                    ),
                    icon: const Icon(Icons.add, color: DesignTokens.colorPrimary),
                  ),
                ),
                Expanded(
                  child: TextField(
                    controller: controller,
                    focusNode: focusNode,
                    enabled: canSend,
                    // `chat-messages-send`'s own request schema caps
                    // `content` at 8000 characters (openapi.yaml) — a
                    // client-side cap surfaces that limit directly
                    // instead of letting an over-length message fail
                    // only after a round trip, indistinguishable from a
                    // dropped connection.
                    maxLength: 8000,
                    textInputAction: TextInputAction.send,
                    onSubmitted: canSend ? (_) => onSend() : null,
                    style: DesignTokens.textBodyLg.copyWith(
                      color: DesignTokens.colorTextPrimary,
                    ),
                    decoration: InputDecoration(
                      hintText: 'Escreva uma mensagem...',
                      counterText: '',
                      contentPadding: DesignTokens.textFieldContentPadding,
                      border: const OutlineInputBorder(
                        borderRadius: BorderRadius.all(
                          Radius.circular(DesignTokens.radiusFull),
                        ),
                        borderSide: BorderSide(
                          color: DesignTokens.colorBorder,
                          width: DesignTokens.borderWidthDefault,
                        ),
                      ),
                      enabledBorder: const OutlineInputBorder(
                        borderRadius: BorderRadius.all(
                          Radius.circular(DesignTokens.radiusFull),
                        ),
                        borderSide: BorderSide(
                          color: DesignTokens.colorBorder,
                          width: DesignTokens.borderWidthDefault,
                        ),
                      ),
                      focusedBorder: const OutlineInputBorder(
                        borderRadius: BorderRadius.all(
                          Radius.circular(DesignTokens.radiusFull),
                        ),
                        borderSide: BorderSide(
                          color: DesignTokens.colorPrimary,
                          width: DesignTokens.borderWidthEmphasis,
                        ),
                      ),
                    ),
                  ),
                ),
                Semantics(
                  button: true,
                  label: 'Enviar mensagem',
                  excludeSemantics: true,
                  child: IconButton(
                    onPressed: canSend ? onSend : null,
                    icon: Icon(
                      Icons.send,
                      color: canSend
                          ? DesignTokens.colorPrimary
                          : DesignTokens.colorTextSecondary,
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';
import '../../domain/entities/chat_message.dart';
import '../cubit/chat_state.dart';

/// One message bubble — user (Boundaries: `colorChatBubbleUser`, squared
/// bottom-right corner) vs AI (`colorSurfaceElevated`, squared bottom-left
/// corner, resting [DesignTokens.elevation1]). Exactly the 3 visible
/// states RF04's Acceptance Criteria names render here, driven by
/// [ChatUiMessage.status]: `streaming` (progressive text + blinking
/// cursor), `failed` (a generic error indicator replaces the timestamp
/// slot — never the tap-to-retry copy, Boundaries: "generic error
/// indicator (not retry copy)" — Story 6.3's job), `complete` (plain
/// text, nothing else). [ChatUiMessage.content] itself is rendered as-is
/// in every state — never cleared on failure (I/O matrix).
class ChatBubble extends StatefulWidget {
  const ChatBubble({required this.message, super.key});

  final ChatUiMessage message;

  @override
  State<ChatBubble> createState() => _ChatBubbleState();
}

class _ChatBubbleState extends State<ChatBubble>
    with SingleTickerProviderStateMixin {
  late final AnimationController _cursorController;

  @override
  void initState() {
    super.initState();
    _cursorController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 600),
    );
    _syncCursorAnimation();
  }

  @override
  void didUpdateWidget(ChatBubble oldWidget) {
    super.didUpdateWidget(oldWidget);
    _syncCursorAnimation();
  }

  /// Keeps the ticker running only while actually needed — a message
  /// that finalizes to `complete`/`failed` must stop ticking forever
  /// after, both so a long-lived chat session never leaks one live
  /// `AnimationController` per past message, and so nothing waiting on
  /// "every animation in the tree has settled" (e.g. a test's own
  /// `pumpAndSettle()`) ever blocks on a bubble that finished streaming.
  void _syncCursorAnimation() {
    final shouldAnimate = widget.message.status == ChatMessageStatus.streaming;
    if (shouldAnimate && !_cursorController.isAnimating) {
      _cursorController.repeat(reverse: true);
    } else if (!shouldAnimate && _cursorController.isAnimating) {
      _cursorController.stop();
    }
  }

  @override
  void dispose() {
    _cursorController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final message = widget.message;
    final isUser = message.role == ChatMessageRole.user;
    // Boundaries: "cursor skipped under
    // `MediaQuery.of(context).disableAnimations`" — the real token text
    // itself always reveals as real tokens actually arrive (there is no
    // separate typing-speed animation to collapse here), only the
    // blinking-cursor glyph is conditional on Reduce Motion.
    final reduceMotion = MediaQuery.of(context).disableAnimations;
    final showCursor =
        message.status == ChatMessageStatus.streaming && !reduceMotion;

    return Align(
      alignment: isUser ? Alignment.centerRight : Alignment.centerLeft,
      child: Container(
        margin: const EdgeInsets.only(bottom: DesignTokens.chatBubbleGap),
        constraints: BoxConstraints(
          maxWidth:
              MediaQuery.of(context).size.width *
              DesignTokens.chatBubbleMaxWidthFraction,
        ),
        padding: DesignTokens.chatBubblePadding,
        decoration: BoxDecoration(
          color: isUser
              ? DesignTokens.colorChatBubbleUser
              : DesignTokens.colorSurfaceElevated,
          borderRadius: BorderRadius.only(
            topLeft: const Radius.circular(DesignTokens.radiusMd),
            topRight: const Radius.circular(DesignTokens.radiusMd),
            bottomLeft: Radius.circular(isUser ? DesignTokens.radiusMd : 0),
            bottomRight: Radius.circular(isUser ? 0 : DesignTokens.radiusMd),
          ),
          boxShadow: isUser ? null : DesignTokens.elevation1,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text.rich(
              TextSpan(
                children: [
                  TextSpan(text: message.content),
                  if (showCursor)
                    WidgetSpan(
                      alignment: PlaceholderAlignment.middle,
                      child: ExcludeSemantics(
                        child: FadeTransition(
                          opacity: _cursorController,
                          child: const Text('▏'),
                        ),
                      ),
                    ),
                ],
              ),
              style: DesignTokens.textBodyLg.copyWith(
                color: DesignTokens.colorTextPrimary,
              ),
            ),
            if (message.status == ChatMessageStatus.failed) ...[
              const SizedBox(height: DesignTokens.spacingXs),
              Container(
                padding: DesignTokens.chatFailureIndicatorPadding,
                decoration: const BoxDecoration(
                  color: DesignTokens.colorErrorBg,
                  borderRadius: BorderRadius.all(
                    Radius.circular(DesignTokens.radiusSm),
                  ),
                ),
                child: Text(
                  'Falha ao gerar resposta',
                  style: DesignTokens.textCaptionSm.copyWith(
                    color: DesignTokens.colorError,
                  ),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';
import '../../domain/entities/sync_badge_state.dart';

/// `EntryRecordCard`'s own sync badge (Code Map) — a colored dot
/// ([DesignTokens.colorWarningSync]/[DesignTokens.colorSuccess]/
/// [DesignTokens.colorError]) plus its text label, always visible (not
/// hidden behind a tap). "Accessible label on tap/long-focus" is split
/// across two single-purpose widgets rather than two that both also
/// announce it: the dot's [Tooltip] (`excludeFromSemantics: true`) gives
/// the *visual* long-press popup only, while the one [Semantics] node
/// wrapping the whole badge (below) is the single accessibility
/// announcement on focus — code-review round 1 finding: a [Tooltip] left
/// at its default `excludeFromSemantics: false` injects its own semantics
/// label too, so pairing it with an outer [Semantics] of the same label
/// double-announced it to screen readers.
///
/// Only an [SyncBadgeError] badge is ever tappable (Boundaries): a
/// [Failure.retryable] one calls [onRetryTap] on tap (I/O matrix: "Tap
/// calls `tracker.retry(tempId)`, re-sends same payload"); a
/// non-retryable one instead toggles an inline explanation
/// ([SyncBadgeError.failure]'s own `message`) with no network call and no
/// retry affordance (Boundaries: "else render inline explanation text, no
/// tap affordance"). [SyncBadgeSynchronizing]/[SyncBadgeSynchronized] are
/// never tappable at all.
class SyncBadge extends StatefulWidget {
  const SyncBadge({
    required this.state,
    this.onRetryTap,
    this.compact = false,
    super.key,
  });

  final SyncBadgeState state;

  /// Called on tap only for a retryable [SyncBadgeError] — ignored (never
  /// even referenced) for every other state, and for a non-retryable
  /// error (Boundaries: "no tap affordance" there means no retry action,
  /// not no tap at all — tapping a non-retryable error still reveals its
  /// explanation, just never calls this).
  final VoidCallback? onRetryTap;

  /// `EntryRecordCard`'s own variant (correction) — `cerne-prototype.html`'s
  /// Tela 4 record card renders the label lowercase in plain
  /// `colorTextSecondary`, next to the colored dot, not the state's own
  /// color; `EntryDetailScreen` (no prototype ground truth for that
  /// screen) keeps the default colored/capitalized rendering, so this is
  /// opt-in rather than this widget's new default.
  final bool compact;

  @override
  State<SyncBadge> createState() => _SyncBadgeState();
}

class _SyncBadgeState extends State<SyncBadge> {
  bool _explanationExpanded = false;

  @override
  void didUpdateWidget(SyncBadge oldWidget) {
    super.didUpdateWidget(oldWidget);
    // A retry attempt (or any other state transition) collapses a
    // previously-shown explanation — stale text from a superseded
    // failure should never linger once the badge has moved on (e.g.
    // synchronizing -> a *new* error after a retry that fails again).
    if (widget.state != oldWidget.state) {
      _explanationExpanded = false;
    }
  }

  @override
  Widget build(BuildContext context) {
    final state = widget.state;
    final (color, label) = switch (state) {
      SyncBadgeSynchronizing() => (
        DesignTokens.colorWarningSync,
        'Sincronizando',
      ),
      SyncBadgeSynchronized() => (DesignTokens.colorSuccess, 'Sincronizado'),
      SyncBadgeError() => (DesignTokens.colorError, 'Erro de sincronização'),
    };

    // Reuses the existing kanban color-dot token (8dp) rather than a new
    // literal (RNF08) — same shape/role (a small colored status dot), just
    // a different screen. `excludeFromSemantics: true` (Review finding):
    // the outer `Semantics(label: label)` below is this badge's one and
    // only accessibility announcement — this Tooltip exists purely for
    // its own visual long-press popup.
    final dot = Tooltip(
      message: label,
      excludeFromSemantics: true,
      child: Container(
        width: DesignTokens.kanbanDotSize,
        height: DesignTokens.kanbanDotSize,
        decoration: BoxDecoration(color: color, shape: BoxShape.circle),
      ),
    );

    // [compact]: lowercase text in `colorTextSecondary` instead of the
    // state's own color — the dot alone still carries that color. Only
    // the *visible* text changes; [label] itself (the accessible string
    // below) stays capitalized either way.
    final displayLabel = widget.compact ? label.toLowerCase() : label;
    final textColor = widget.compact ? DesignTokens.colorTextSecondary : color;

    // `ExcludeSemantics` (Review finding): without it, the visible `Text`
    // below contributes its *own* implicit semantics label ("Sincronizando",
    // same string) that merges straight into the explicit `Semantics(label:
    // label)` container wrapping this whole row — doubling the announced
    // label even after the dot's own `Tooltip` was already excluded above.
    // The one `Semantics(label: label)` node is this badge's single source
    // of truth for its accessible text; this row is purely visual.
    final labelRow = ExcludeSemantics(
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          dot,
          const SizedBox(width: DesignTokens.spacingXs),
          Text(
            displayLabel,
            style: DesignTokens.textMonoCaption.copyWith(color: textColor),
          ),
        ],
      ),
    );

    if (state is! SyncBadgeError) {
      // `container: true` (Review finding) — without it, a `Semantics`
      // widget with no interactive descendant doesn't form its own node;
      // Flutter merges its `label` up into the nearest explicit container
      // ancestor instead (e.g. the Scaffold's own), so `label` alone is
      // never exactly what a screen reader (or `find.bySemanticsLabel`)
      // reports for this widget specifically.
      return Semantics(label: label, container: true, child: labelRow);
    }

    final retryable = state.failure.retryable;
    return Semantics(
      label: label,
      container: true,
      button: true,
      child: InkWell(
        onTap: () {
          if (retryable) {
            widget.onRetryTap?.call();
          } else {
            setState(() => _explanationExpanded = !_explanationExpanded);
          }
        },
        child: ConstrainedBox(
          constraints: const BoxConstraints(
            minWidth: DesignTokens.insertionModalTapTargetMin,
            minHeight: DesignTokens.insertionModalTapTargetMin,
          ),
          child: Align(
            alignment: Alignment.centerLeft,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                labelRow,
                if (!retryable && _explanationExpanded)
                  Padding(
                    padding: const EdgeInsets.only(top: DesignTokens.spacingXs),
                    child: Text(
                      state.failure.message,
                      style: DesignTokens.textCaptionSm.copyWith(
                        color: DesignTokens.colorTextSecondary,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

